def minSwaps(nums):
    # Relative order within each parity class is preserved; the minimum adjacent swaps
    # to move a class to target positions [0,2,4,...] is sum |current_index - target|.
    even_pos = [i for i, x in enumerate(nums) if x % 2 == 0]
    odd_pos = [i for i, x in enumerate(nums) if x % 2 == 1]
    E, O = len(even_pos), len(odd_pos)

    def cost(positions):
        return sum(abs(p - 2 * i) for i, p in enumerate(positions))

    if abs(E - O) > 1:
        return -1
    if E > O:            # evens occupy even indices
        return cost(even_pos)
    if O > E:            # odds occupy even indices
        return cost(odd_pos)
    # equal counts: evens at even indices, or evens at odd indices
    c1 = cost(even_pos)
    c2 = sum(abs(p - (2 * i + 1)) for i, p in enumerate(even_pos))
    return min(c1, c2)
